// Announcement popup: only hints that something big is coming and takes visitors straight to the Upcoming events page.
// All the information stays on that page. Shows once per visit (after the opening animation).
//
// It shows up while SHOW_UPCOMING is true and an upcoming event exists (the mystery card is on, or a real event is
// in data/site.js), and goes away by itself when that event is over.
// The design comes by itself (it matches the Upcoming card and moves on with every new event, see site/designs.js).
//
// You do not edit this file. Everything is in site/upcomingConfig.js (SHOW_UPCOMING, EVENT_TYPE, POPUP_TEXT ...)
// and the on/off switches are in site/eventSwitches.js (Code Clash popup, Vibe-A-Thon popup).
// Only one popup shows per visit. The Code Clash popup scrolls to the Code Clash block on the Home page; the Vibe-A-Thon one opens /upcoming.
import { useCallback, useEffect, useRef, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useIntroDone } from './ui';
import { useUpcoming } from './events';
import { EVENT_NAME, HAS_DETAILS, getDesign, isTeaserLive } from './teaserCore';
import {
  SHOW_UPCOMING, SHOW_POPUP, POPUP_TEXT, POPUP_SHOW_NAME, POPUP_DELAY, POPUP_SEEN_KEY, POPUP_SKIP_ON,
} from './upcomingConfig';
import { NEW_POPUPS, POPUP_NAMES } from './designs';
import {
  CODE_CLASH_POPUP, VIBEATHON_POPUP, CODE_CLASH_SECTION, CODE_CLASH_ID, CODE_CLASH_SEEN_KEY, CODE_CLASH_SKIP_ON,
} from './eventSwitches';
import './AnnouncePopup.css';

const STYLES = POPUP_NAMES;
const pick = (name) => (STYLES.includes(String(name).toLowerCase()) ? String(name).toLowerCase() : null);

// ?popup=glitch at the end of the address previews that popup (it ignores "already seen" and the switches)
const previewName = () => {
  try { return pick(new URLSearchParams(window.location.search).get('popup')); } catch { return null; }
};

// ?popup=clash previews the Code Clash popup
const clashPreviewOn = () => {
  try { return new URLSearchParams(window.location.search).get('popup') === 'clash'; } catch { return false; }
};

let handled = false; // also remembers "already shown" (one popup per visit) when the browser blocks sessionStorage
const wasSeen = (key) => {
  if (handled) return true;
  try { return window.sessionStorage.getItem(key) === '1'; } catch { return false; }
};
const markSeen = (key) => {
  handled = true;
  try { window.sessionStorage.setItem(key, '1'); } catch { /* storage blocked: the variable above is enough */ }
};

export default function AnnouncePopup() {
  const introDone = useIntroDone();
  const { pathname } = useLocation();
  const navigate = useNavigate();
  const upcoming = useUpcoming();
  const [open, setOpen] = useState(false);
  const [closing, setClosing] = useState(false);
  const [view, setView] = useState(null);       // { Design, name } once the chosen design has loaded
  const back = useRef(null);
  const card = useRef(null);
  const cta = useRef(null);
  const from = useRef(null);

  const design = getDesign();
  const vibePreview = previewName() || (design.preview ? design.popup : null);   // ?popup=glitch or ?design=4 in the address
  // Code Clash popup: on while its switch and the block's switch are on (eventSwitches.js). It wins over the Vibe-A-Thon one.
  const clashPreview = !vibePreview && clashPreviewOn();
  const clash = clashPreview || (!vibePreview && CODE_CLASH_POPUP && CODE_CLASH_SECTION);
  const preview = clashPreview ? 'clash' : vibePreview;
  const seenKey = clash ? CODE_CLASH_SEEN_KEY : POPUP_SEEN_KEY;
  const skip = !preview && (clash ? CODE_CLASH_SKIP_ON : POPUP_SKIP_ON).includes(pathname);
  // Vibe-A-Thon: is there an upcoming event that is not over yet?
  const active = clash || !!preview || (VIBEATHON_POPUP && SHOW_UPCOMING && SHOW_POPUP && (isTeaserLive() || upcoming.length > 0));
  const name = clash ? 'clash' : (preview || pick(design.popup) || 'radar');

  // open it once the opening animation is over (the design is loaded first, so nothing flashes)
  useEffect(() => {
    if (!introDone || skip || !active || (!preview && wasSeen(seenKey))) return undefined;
    let dead = false;
    let id = 0;
    const load = clash ? import('./CodeClashPopup') : (NEW_POPUPS.includes(name) ? import('./PopupStylesNew') : import('./PopupStyles'));
    load.then((m) => {
      if (dead) return;
      id = setTimeout(() => {
        if (!preview && wasSeen(seenKey)) return;
        from.current = document.activeElement;
        if (!preview) markSeen(seenKey);
        setView({ Design: m.default, name });
        setOpen(true);
      }, POPUP_DELAY);
    }).catch(() => { /* the design could not load (offline): just skip the popup */ });
    return () => { dead = true; clearTimeout(id); };
  }, [introDone, skip, active, preview, name, clash, seenKey]);

  const close = useCallback(() => {
    setClosing(true);
    setTimeout(() => {
      setOpen(false);
      setClosing(false);
      const el = from.current;
      if (el && el.focus && document.contains(el)) el.focus({ preventScroll: true });
    }, 240);
  }, []);

  // while it is open: Esc closes, Tab stays inside, the page behind does not scroll
  useEffect(() => {
    if (!open) return undefined;
    const t = setTimeout(() => { if (cta.current) cta.current.focus({ preventScroll: true }); }, 60);
    const onKey = (e) => {
      if (e.key === 'Escape') { close(); return; }
      if (e.key !== 'Tab' || !card.current) return;
      const items = [...card.current.querySelectorAll('button, a[href]')].filter((n) => !n.disabled);
      if (!items.length) return;
      const first = items[0], last = items[items.length - 1];
      if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
      else if (!card.current.contains(document.activeElement)) { e.preventDefault(); first.focus(); }
    };
    const b = back.current;
    const stop = (e) => { if (!card.current || !card.current.contains(e.target)) e.preventDefault(); };
    document.addEventListener('keydown', onKey);
    if (b) { b.addEventListener('wheel', stop, { passive: false }); b.addEventListener('touchmove', stop, { passive: false }); }
    return () => {
      clearTimeout(t);
      document.removeEventListener('keydown', onKey);
      if (b) { b.removeEventListener('wheel', stop); b.removeEventListener('touchmove', stop); }
    };
  }, [open, close]);

  // "See what's coming": open the Upcoming events page (in a ?design=N preview it keeps the matching card)
  const go = () => {
    from.current = null;
    if (clash) {
      // Code Clash: only takes people to the block (the form opens from the block's own Register now button)
      if (pathname === '/') {
        const el = document.getElementById(CODE_CLASH_ID);
        if (el) el.scrollIntoView({ behavior: 'smooth' });
      } else {
        navigate({ pathname: '/', hash: `#${CODE_CLASH_ID}` });   // Layout.jsx scrolls to the id once the Home page is open
      }
      close();
      return;
    }
    navigate(design.preview ? `/upcoming?design=${design.preview}` : '/upcoming');
    close();
  };

  if (!open || !view) return null;

  // once the event name is announced the popup can say it (turn it off with POPUP_SHOW_NAME = false)
  const named = POPUP_SHOW_NAME && !!EVENT_NAME;
  // once you fill in details the popup says so too, so people know there is something new to unlock
  const news = HAS_DETAILS ? 'New details are unlocked. Tap below, then press Try to decrypt.' : null;
  const text = named
    ? { ...POPUP_TEXT, title: `${EVENT_NAME} is coming`, name: EVENT_NAME, rest: 'is coming', desc: news || 'Tap below to see all the details on the Upcoming events page.', flag: 'Now announced' }
    : { ...POPUP_TEXT, desc: news || POPUP_TEXT.desc, flag: HAS_DETAILS ? 'New details unlocked' : 'New signal detected' };
  const { Design } = view;

  return (
    <div
      ref={back}
      className={`s-ann is-${view.name} ${closing ? 'is-out' : ''}`}
      onMouseDown={(e) => { if (e.target === e.currentTarget) close(); }}
    >
      <Design name={view.name} text={text} onGo={go} onClose={close} cardRef={card} ctaRef={cta} />
    </div>
  );
}
